    "  ): js.Dictionary[js.Dictionary[js.Any]] = {",
    "    val cloned = js.Dictionary.empty[js.Dictionary[js.Any]]",
    "    source.foreach { case (key, value) => cloned.update(key, cloneDictionary(value)) }",
